// Verify Cal.com HMAC-SHA256 signature.
// Cal.com: header `x-cal-signature-256` = hex( HMAC_SHA256(secret, raw_body) )
const crypto = require('crypto');

const secret = $env.CALCOM_WEBHOOK_SIGNING_SECRET;
if (!secret) throw new Error('server_misconfigured: CALCOM_WEBHOOK_SIGNING_SECRET not set');

const input = $input.first().json;
const headers = input.headers || {};
const given = (headers['x-cal-signature-256'] || headers['X-Cal-Signature-256'] || '').toLowerCase();

// Webhook node with rawBody=true exposes the raw bytes on `body` (string)
const rawBody = typeof input.body === 'string' ? input.body : JSON.stringify(input.body || {});

const expected = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');

let ok = false;
try {
  ok = given.length === expected.length && crypto.timingSafeEqual(
    Buffer.from(given, 'utf8'),
    Buffer.from(expected, 'utf8'),
  );
} catch { ok = false; }

if (!ok) {
  throw new Error('invalid_signature');
}

// Parse body now that it's verified
let payload;
try { payload = typeof input.body === 'string' ? JSON.parse(input.body) : input.body; }
catch (e) { throw new Error('invalid_json_body'); }

return { event: payload };

// Normalize the booking event into a uniform shape downstream nodes can use.
// Handles BOOKING_CREATED, BOOKING_RESCHEDULED, BOOKING_CANCELLED.
const e = $input.first().json.event;
const trigger = e.triggerEvent || e.event || 'BOOKING_CREATED';
const p = e.payload || e;

// Cal.com nests differently across versions; cover both shapes
const attendees = Array.isArray(p.attendees) ? p.attendees : [];
const primary = attendees[0] || {};

const email = String(p.invitee?.email || primary.email || p.responses?.email?.value || '').toLowerCase().trim();
const name  = p.invitee?.name || primary.name || p.responses?.name?.value || (email ? email.split('@')[0] : 'Unknown');
const startTime = p.startTime || p.scheduled_event?.start_time || p.start_time;
const endTime   = p.endTime   || p.scheduled_event?.end_time   || p.end_time;
const eventTitle = p.title || p.eventType?.title || p.scheduled_event?.name || '30-min meeting';

// Cal.com puts join URL in different places depending on integration
let joinUrl = '';
if (typeof p.location === 'string' && p.location.startsWith('http')) joinUrl = p.location;
else if (p.location?.join_url) joinUrl = p.location.join_url;
else if (Array.isArray(p.metadata?.videoCallUrl)) joinUrl = p.metadata.videoCallUrl[0];
else if (typeof p.metadata?.videoCallUrl === 'string') joinUrl = p.metadata.videoCallUrl;
else if (p.scheduled_event?.location?.join_url) joinUrl = p.scheduled_event.location.join_url;

const bookingUid = p.uid || p.bookingUid || p.scheduled_event?.uri || '';

// Pull free-text fields from Cal.com's booking-question responses
const responses = p.responses || {};
const notes = Object.entries(responses)
  .filter(([k]) => !['name','email','guests','smsReminderNumber'].includes(k))
  .map(([k, v]) => `${k}: ${typeof v === 'object' ? (v.value || JSON.stringify(v)) : v}`)
  .join('\n');

const company = responses.company?.value || responses.organization?.value || '';
const phone   = responses.phone?.value   || responses.smsReminderNumber || '';

if (!email) throw new Error('booking_email_missing');
if (!bookingUid) throw new Error('booking_uid_missing');

return {
  trigger,
  email,
  name,
  company,
  phone,
  start_time: startTime,
  end_time:   endTime,
  join_url:   joinUrl,
  event_title: eventTitle,
  booking_uid: bookingUid,
  notes,
};

